import java.util.*;

public class GraphTraversalIterator implements Iterator<Integer> {
    private final List<Integer> vertices;
    private final Set<Integer> visited;
    private int cursor;

    public GraphTraversalIterator(List<Integer> vertices) {
        this.vertices = new ArrayList<>(vertices);
        this.visited = new HashSet<>();
        this.cursor = 0;
    }

    @Override
    public boolean hasNext() {
        while (cursor < vertices.size() && visited.contains(vertices.get(cursor))) {
            cursor++;
        }
        return cursor < vertices.size();
    }

    @Override public Integer next() {
        if (!hasNext()) throw new NoSuchElementException();
        int v = vertices.get(cursor);
        visited.add(v);
        cursor++;
        return v;
    }
}

