private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == this) return;
    // Acquire locks in consistent order to avoid deadlock
    Object firstLock = this;
    Object secondLock = list;
    if (System.identityHashCode(firstLock) > System.identityHashCode(secondLock)) {
        Object temp = firstLock;
        firstLock = secondLock;
        secondLock = temp;
    }
    synchronized (firstLock) {
        synchronized (secondLock) {
            // Get first real node from other list
            ListNode<E> otherFirst = list.head.next;
            if (otherFirst == list.tail) { // empty
                return;
            }
            // Get last real node
            ListNode<E> otherLast = list.tail.prev;
            // Connect this list's tail.prev to otherFirst
            this.tail.prev.next = otherFirst;
            otherFirst.prev = this.tail.prev;
            // Connect other's last to this list's tail
            otherLast.next = this.tail;
            this.tail.prev = otherLast;
            // Update size
            this.size += list.size;
            // Empty the other list
            list.head.next = list.tail;
            list.tail.prev = list.head;
            list.size = 0;
        }
    }
}

